import java.io.*;
import java.util.*;

public class Main {
    static int N, Q;
    static long K;
    static int[] A;
    static boolean[] deleted;
    static int[] D;
    static boolean[] inserted;
    static int[] parent, sz, mn, mx;
    static ArrayList<Integer>[] elems;
    static HashMap<Long, Integer>[] plusMap, minusMap;
    static long total = 0;

    static int[] left, right, szTreap, hTreap, prio;
    static int nodeCnt = 0;
    static Random rnd = new Random(12345);

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Integer.parseInt(st.nextToken());
        Q = Integer.parseInt(st.nextToken());
        K = Long.parseLong(st.nextToken());

        A = new int[N];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) A[i] = Integer.parseInt(st.nextToken());

        D = new int[Q];
        deleted = new boolean[N];
        for (int i = 0; i < Q; i++) {
            D[i] = Integer.parseInt(br.readLine()) - 1;
            deleted[D[i]] = true;
        }

        inserted = new boolean[N];
        parent = new int[N];
        sz = new int[N];
        mn = new int[N];
        mx = new int[N];
        elems = new ArrayList[N];
        plusMap = new HashMap[N];
        minusMap = new HashMap[N];

        int maxNodes = 2 * N + 5;
        left = new int[maxNodes];
        right = new int[maxNodes];
        szTreap = new int[maxNodes];
        hTreap = new int[maxNodes];
        prio = new int[maxNodes];

        // Insert all non-deleted positions in increasing order
        for (int i = 0; i < N; i++) {
            if (!deleted[i]) insertPosition(i);
        }

        long[] ans = new long[Q + 1];
        ans[Q] = total;

        // Insert deleted positions in reverse order
        for (int t = Q - 1; t >= 0; t--) {
            insertPosition(D[t]);
            ans[t] = total;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i <= Q; i++) {
            sb.append(ans[i]).append('\n');
        }
        System.out.print(sb);
    }

    static int newNode(int height) {
        nodeCnt++;
        hTreap[nodeCnt] = height;
        prio[nodeCnt] = rnd.nextInt();
        szTreap[nodeCnt] = 1;
        left[nodeCnt] = right[nodeCnt] = 0;
        return nodeCnt;
    }

    static void insertPosition(int idx) {
        inserted[idx] = true;
        parent[idx] = idx;
        sz[idx] = 1;
        mn[idx] = mx[idx] = idx;

        ArrayList<Integer> e = new ArrayList<>();
        e.add(idx);
        elems[idx] = e;

        int pNode = newNode(A[idx]);
        plusMap[idx] = new HashMap<>();
        plusMap[idx].put((long) A[idx] + idx, pNode);

        int mNode = newNode(A[idx]);
        minusMap[idx] = new HashMap<>();
        minusMap[idx].put((long) A[idx] - idx, mNode);

        if (idx > 0 && inserted[idx - 1]) {
            union(find(idx), find(idx - 1));
        }
        if (idx + 1 < N && inserted[idx + 1]) {
            union(find(idx), find(idx + 1));
        }
    }

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static void union(int r1, int r2) {
        if (r1 == r2) return;
        int s, l;
        if (sz[r1] < sz[r2]) {
            s = r1;
            l = r2;
        } else {
            s = r2;
            l = r1;
        }

        if (mx[s] < mn[l]) {
            // s is left of l, target is right
            for (int p : elems[s]) {
                total += queryRight(p, l);
            }
        } else {
            // l is left of s, target is left
            for (int p : elems[s]) {
                total += queryLeft(p, l);
            }
        }

        mergeMaps(l, s);

        elems[l].addAll(elems[s]);
        elems[s] = null;
        plusMap[s] = null;
        minusMap[s] = null;
        parent[s] = l;
        sz[l] += sz[s];
        if (mn[s] < mn[l]) mn[l] = mn[s];
        if (mx[s] > mx[l]) mx[l] = mx[s];
    }

    static long queryRight(int p, int target) {
        int a = A[p];
        long ans = 0;

        long v1 = (long) a + p + K;
        Integer root1 = plusMap[target].get(v1);
        if (root1 != null) ans += countGT(root1, a);

        long v2 = (long) a - p - K;
        Integer root2 = minusMap[target].get(v2);
        if (root2 != null) ans += countLE(root2, a);

        return ans;
    }

    static long queryLeft(int p, int target) {
        int a = A[p];
        long ans = 0;

        long v1 = (long) a + p - K;
        Integer root1 = plusMap[target].get(v1);
        if (root1 != null) ans += countLE(root1, a);

        long v2 = (long) a - p + K;
        Integer root2 = minusMap[target].get(v2);
        if (root2 != null) ans += countGT(root2, a);

        return ans;
    }

    static int countLE(int root, int H) {
        int ans = 0;
        int cur = root;
        while (cur != 0) {
            if (hTreap[cur] <= H) {
                ans += szTreap[left[cur]] + 1;
                cur = right[cur];
            } else {
                cur = left[cur];
            }
        }
        return ans;
    }

    static int countGT(int root, int H) {
        if (root == 0) return 0;
        return szTreap[root] - countLE(root, H);
    }

    static void mergeMaps(int l, int s) {
        for (Map.Entry<Long, Integer> e : plusMap[s].entrySet()) {
            long key = e.getKey();
            int srcRoot = e.getValue();
            Integer dstRoot = plusMap[l].get(key);
            if (dstRoot == null) {
                plusMap[l].put(key, srcRoot);
            } else {
                plusMap[l].put(key, mergeTreap(srcRoot, dstRoot));
            }
        }
        for (Map.Entry<Long, Integer> e : minusMap[s].entrySet()) {
            long key = e.getKey();
            int srcRoot = e.getValue();
            Integer dstRoot = minusMap[l].get(key);
            if (dstRoot == null) {
                minusMap[l].put(key, srcRoot);
            } else {
                minusMap[l].put(key, mergeTreap(srcRoot, dstRoot));
            }
        }
    }

    static int mergeTreap(int src, int dst) {
        if (src == 0) return dst;
        dst = mergeTreap(left[src], dst);
        int rightChild = right[src];
        left[src] = right[src] = 0;
        szTreap[src] = 1;
        dst = insert(dst, src);
        dst = mergeTreap(rightChild, dst);
        return dst;
    }

    static int insert(int root, int node) {
        if (root == 0) return node;
        if (hTreap[node] < hTreap[root]) {
            left[root] = insert(left[root], node);
            if (prio[left[root]] > prio[root]) root = rotateRight(root);
        } else {
            right[root] = insert(right[root], node);
            if (prio[right[root]] > prio[root]) root = rotateLeft(root);
        }
        update(root);
        return root;
    }

    static int rotateRight(int p) {
        int q = left[p];
        left[p] = right[q];
        right[q] = p;
        update(p);
        update(q);
        return q;
    }

    static int rotateLeft(int p) {
        int q = right[p];
        right[p] = left[q];
        left[q] = p;
        update(p);
        update(q);
        return q;
    }

    static void update(int x) {
        szTreap[x] = 1 + szTreap[left[x]] + szTreap[right[x]];
    }
}
